package com.zenitrade.controller; import com.zenitrade.entity.*; import com.zenitrade.repository.*; import com.zenitrade.service.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/api") public class PortfolioController {private final CurrentUser cu;private final HoldingRepository holdings;private final TradeRepository trades;private final TradeService service;public PortfolioController(CurrentUser c,HoldingRepository h,TradeRepository t,TradeService s){cu=c;holdings=h;trades=t;service=s;} public record Order(String symbol,int quantity,String side,String productType){} @GetMapping("/portfolio") Map<String,Object> portfolio(){User u=cu.get();List<Holding> hs=holdings.findByUserId(u.id);BigDecimal value=hs.stream().map(h->h.stock.currentPrice.multiply(BigDecimal.valueOf(h.quantity))).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("cash",u.virtualCash,"holdingsValue",value,"totalValue",value.add(u.virtualCash),"holdings",hs);} @GetMapping("/trades") List<Trade> trades(){return trades.findByUserIdOrderByExecutedAtDesc(cu.get().id);} @PostMapping("/trades") Trade order(@RequestBody Order o){return service.execute(o.symbol(),o.quantity(),o.side(),o.productType()==null?"DELIVERY":o.productType());} }
